import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { Box, Typography, Button, CircularProgress } from "@mui/material";
import { supabase } from "../supabase";

const VerifyPage = () => {
  const [status, setStatus] = useState("checking");
  const [errorMsg, setErrorMsg] = useState("");
  const navigate = useNavigate();

  useEffect(() => {
    const verifyUser = async () => {
      console.log("🔍 Starting verification...");
      console.log("🌐 Full URL:", window.location.href);

      try {
        // ✅ For OTP-based sign in
        const { error: otpError } = await supabase.auth.exchangeCodeForSession(); // ✅ correct in Supabase v2


        if (otpError) {
          console.error("❌ OTP session error:", otpError.message);
          setErrorMsg("Verification failed. The link may have expired or was already used.");
          setStatus("failed");
          return;
        }

        console.log("✅ OTP session handled. Fetching user...");

        const { data: userData, error: userError } = await supabase.auth.getUser();

        if (userError || !userData?.user?.email_confirmed_at) {
          console.warn("⚠️ Email not confirmed or user missing.");
          setErrorMsg("Unable to verify your email. Try signing up again.");
          setStatus("failed");
          return;
        }

        const userId = userData.user.id;
        const saved = JSON.parse(localStorage.getItem("signup_user"));

        if (saved) {
          const { name, dob, role } = saved;
          console.log("📦 Inserting profile data:", saved);

          const { error: insertError } = await supabase.from("profiles").insert([
            { id: userId, name, dob, role },
          ]);

          if (insertError) {
            console.error("❌ Failed to insert profile:", insertError.message);
            setErrorMsg("Could not save your profile. Try again later.");
            setStatus("failed");
            return;
          }
        } else {
          console.warn("⚠️ No profile info in localStorage.");
        }

        localStorage.removeItem("signup_user");
        setStatus("success");
        setTimeout(() => {
          navigate("/dashboard");
        }, 2000);
      } catch (err) {
        console.error("🔥 Unexpected error:", err);
        setErrorMsg("Something went wrong. Please try again.");
        setStatus("failed");
      }
    };

    verifyUser();
  }, [navigate]);

  return (
    <Box
      sx={{
        height: "100vh",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        flexDirection: "column",
        textAlign: "center",
        px: 3,
      }}
    >
      {status === "checking" && (
        <>
          <CircularProgress sx={{ color: "#8E2839", mb: 2 }} />
          <Typography variant="h6" color="#8E2839">
            Verifying your account...
          </Typography>
        </>
      )}

      {status === "success" && (
        <>
          <Typography variant="h6" color="green" mb={1}>
            ✅ Verification successful!
          </Typography>
          <Typography>Redirecting to your dashboard...</Typography>
        </>
      )}

      {status === "failed" && (
        <>
          <Typography variant="h6" color="red" mb={1}>
            ❌ Verification failed
          </Typography>
          <Typography mb={2}>{errorMsg}</Typography>
          <Button
            variant="contained"
            sx={{ backgroundColor: "#8E2839" }}
            onClick={() => navigate("/signin")}
          >
            Back to Sign In
          </Button>
        </>
      )}
    </Box>
  );
};

export default VerifyPage;
